import pandas as pd


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    if name in inputs:
        return inputs[name]
    # try case-insensitive match
    lower_name = name.lower()
    for k, v in inputs.items():
        if k.lower() == lower_name:
            return v
    raise KeyError(name)


def run(inputs: dict) -> dict:
    postings = _get_input(inputs, "POSTINGS").copy()

    # Preserve original row order for stable tie-breaking
    postings = postings.reset_index(drop=False).rename(columns={"index": "_orig_order"})

    # Sort as the cursor does: account_id, post_date, post_seq
    # Use mergesort (stable) so any residual ties keep original input order.
    postings = postings.sort_values(
        by=["account_id", "post_date", "post_seq"],
        kind="mergesort",
        na_position="first",
    ).reset_index(drop=True)

    posted_rows = []
    reject_rows = []

    prev_acct = None
    tot = 0.0
    rej = 0

    def flush_reject(acct, count):
        reject_rows.append({"account_id": acct, "reject_count": count})

    for _, r in postings.iterrows():
        acct = r["account_id"]

        if acct != prev_acct:
            if prev_acct is not None:
                flush_reject(prev_acct, rej)
            tot = 0.0
            rej = 0
            prev_acct = acct

        qty = r["qty"]
        price = r["unit_price"]

        is_bad = (
            pd.isna(qty)
            or qty <= 0
            or pd.isna(price)
            or price < 0
        )

        if is_bad:
            rej += 1
        else:
            v = qty * price
            tot = tot + v
            posted_rows.append(
                {
                    "account_id": acct,
                    "post_seq": r["post_seq"],
                    "post_date": r["post_date"],
                    "post_value": v,
                    "running_total": tot,
                }
            )

    if prev_acct is not None:
        flush_reject(prev_acct, rej)

    posted_totals = pd.DataFrame(
        posted_rows,
        columns=["account_id", "post_seq", "post_date", "post_value", "running_total"],
    )
    reject_counts = pd.DataFrame(
        reject_rows,
        columns=["account_id", "reject_count"],
    )

    if not posted_totals.empty:
        posted_totals["account_id"] = posted_totals["account_id"].astype(
            postings["account_id"].dtype
        )
        posted_totals["post_seq"] = posted_totals["post_seq"].astype(
            postings["post_seq"].dtype
        )

    if not reject_counts.empty:
        reject_counts["account_id"] = reject_counts["account_id"].astype(
            postings["account_id"].dtype
        )
        reject_counts["reject_count"] = reject_counts["reject_count"].astype(int)

    return {
        "posted_totals": posted_totals,
        "reject_counts": reject_counts,
    }
